//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
)

func TestEnum_ENGINE_CONTROL_OPTIONS(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.ENGINE_CONTROL_OPTIONS
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.ENGINE_CONTROL_OPTIONS_ALLOW_START_WHILE_DISARMED.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.ENGINE_CONTROL_OPTIONS
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.ENGINE_CONTROL_OPTIONS_ALLOW_START_WHILE_DISARMED, dec)
	})
}
